  const profile = path.join(home, ".claude"); const project = path.join(home, "project"); fs.mkdirSync(profile); fs.mkdirSync(path.join(project, ".git"), { recursive: true }); fs.mkdirSync(path.join(project, ".claude"));
  const locations = createLifecycleLocations({ homeDir: home, profilePath: profile, platform: process.platform === "win32" ? "win32" : "posix", project: { activeCheckoutPath: project, checkoutFamilyPath: project } }); if (!locations.ok) throw new Error(locations.error.message);
  const established = await establishOwnedStateStore(locations.value, home); if (!established.ok) throw new Error(established.message);
  const catalogBytes = Buffer.from(JSON.stringify({ name: "official", owner: { name: "Example" }, plugins: [{ name: "other", source: { source: "archive", url: "https://archive.example.org/tool.zip" } }, { name: "tool", source: { source: "archive", url: "https://archive.example.org/tool.zip" } }] })); const catalogDigest = digest(catalogBytes); const source = { kind: "https-catalog", url: "https://catalog.example.org/catalog.json" } as const;
  const snapshotId = `marketplace-${createHash("sha256").update(`${catalogDigest}\0${source.url}`).digest("base64url")}` as const;
  const executableCatalog = deriveExecutableMarketplaceCatalogProjection(catalogBytes, source.kind); if (executableCatalog === undefined) throw new Error("fixture projection"); const target = { authorityKind: "catalog-only", marketplaceName: "official", snapshotId, source, catalogDigest, executableCatalog, provenance: { adapter: "public-https-catalog", canonicalUrl: source.url } } as const;
  const grant = createMarketplaceSnapshotTrustGrant(target); if (!grant.ok) throw new Error(grant.message);
  const raw: OwnedMarketplaceSnapshotRecord = { ownership: "picc-owned", profileKey: established.value.profileKey as `profile-${string}`, ...target, trust: grant.value };
  const snapshotCodec = createOwnedMarketplaceSnapshotCodec({ profileKey: established.value.profileKey as `profile-${string}`, artifactsRoot: established.value.artifactsRoot }); const envelope = createRecordEnvelope(snapshotCodec, "picc-owned", ownedMarketplaceSnapshotScopeKey(raw), raw); if (!envelope.ok) throw new Error(envelope.message);
  const partition = ownedRecordPartition(established.value, "picc-owned", ownedMarketplaceSnapshotScopeKey(raw)); if (!partition.ok) throw new Error(partition.message); fs.mkdirSync(partition.value, { recursive: true }); fs.writeFileSync(path.join(partition.value, "snapshot.json"), envelope.value.bytes);
  const registry = createProducerCodecRegistry([snapshotCodec]); if (!registry.ok) throw new Error(registry.message); const snapshot = readOwnedAdmissionRecords(established.value, registry.value, undefined).marketplaceSnapshots[0]!;
