    const generationBytes = cloneParticipants(); generationBytes.at(-1)!["stagedDigest"] = digest(Buffer.from("contradictory-generation")); const generationTarget = cloneParticipants(); generationTarget.at(-1)!["targetPath"] = `${generationTarget.at(-1)!["targetPath"] as string}.other`; const predecessorBijection = cloneParticipants(); const predecessorEvidence = predecessorBijection.at(-1)!["producerEvidence"] as { predecessor: { installations: unknown[] } }; predecessorEvidence.predecessor.installations = [...predecessorEvidence.predecessor.installations, structuredClone(predecessorEvidence.predecessor.installations[0])]; const selectedAuthority = cloneParticipants(); const selectedRecord = (selectedAuthority[0]!["producerEvidence"] as { record: Record<string, unknown> }).record; selectedRecord["profileKey"] = "profile-contradictory"; const sourceTrust = cloneParticipants(); const sourceRecord = (sourceTrust[0]!["producerEvidence"] as { record: { source: Record<string, unknown>; trust: Record<string, unknown> } }).record; sourceRecord.source["url"] = "https://different.example.org/tool.zip"; sourceRecord.trust["target"] = "other@official"; const destructiveSummary = resign({ ...(structuredClone(journal.value.confirmationSummary) as Record<string, unknown>), action: "uninstall", removeData: true, removeDeclaration: true, consequences: ["Removes only the selected PiCC-owned installation and rebinds every survivor", "Removes the selected authentic enablement declaration", "Logically retires exact last-reference PiCC-owned data; physical cleanup is conservative best effort, not secure erasure", "Retires code only when no owned installation references it", "The running session remains unchanged until reload"] }); const lockSummary = resign({ ...(structuredClone(journal.value.confirmationSummary) as Record<string, unknown>), checkoutFamilyKey: "checkout-contradictory" });
    const selectedGraphSummary = (mutate: (row: Record<string, unknown>, graph: Array<Record<string, unknown>>) => void) => { const summary = structuredClone(journal.value.confirmationSummary) as unknown as Record<string, unknown>; const dependency = summary["dependencies"] as { graph: Array<Record<string, unknown>> }; const selectedRows = dependency.graph.filter((row) => row["pluginId"] === preview.value.pluginId); if (selectedRows.length !== 1) throw new Error("Expected one selected dependency graph row in valid persisted summary"); mutate(selectedRows[0]!, dependency.graph); summary["dependencies"] = pluginDependencyPosture(preview.value.pluginId, dependency.graph as never); return resign(summary); };
    const graphSummaries = [
      ["selected graph plugin identity", selectedGraphSummary((row) => { row["pluginId"] = "mutated@official"; })],
      ["selected graph version", selectedGraphSummary((row) => { row["version"] = "9.9.9"; })],
      ["selected graph ownership", selectedGraphSummary((row) => { row["ownership"] = "claude-imported-readonly"; })],
      ["selected graph enabled posture", selectedGraphSummary((row) => { row["enabled"] = false; })],
      ["selected graph availability", selectedGraphSummary((row) => { row["available"] = false; })],
      ["selected graph dependencies", selectedGraphSummary((row) => { row["dependencies"] = [{ name: "missing", itemIndex: 0 }]; })],
      ["selected graph declaration", selectedGraphSummary((row) => { row["dependencyDeclaration"] = "invalid"; })],
      ["selected graph allowlist", selectedGraphSummary((row) => { row["allowedCrossMarketplaceDependencies"] = ["mutated"]; })],
      ["duplicate selected graph row", selectedGraphSummary((row, graph) => { graph.push(structuredClone(row)); })],
    ] as const;
    for (const [name, participants, summary] of [["generation bytes", generationBytes, journal.value.confirmationSummary], ["generation target", generationTarget, journal.value.confirmationSummary], ["predecessor bijection", predecessorBijection, journal.value.confirmationSummary], ["selected authority", selectedAuthority, journal.value.confirmationSummary], ["source/trust", sourceTrust, journal.value.confirmationSummary], ["destructive order/flags", journal.value.participants, destructiveSummary], ["locks/summary", journal.value.participants, lockSummary], ...graphSummaries.map(([name, summary]) => [name, journal.value.participants, summary] as const)] as const) { const result = codec.requiredLocks(summary, participants as never); expect(result, name).toMatchObject({ ok: false }); }
    expect(journal.value.requiredLocks).toEqual([{ kind: "profile", key: value.store.profileKey }, { kind: "checkout", key: value.checkoutFamilyKey }, expect.objectContaining({ kind: "settings" })]); expect(codec.requiredLocks(journal.value.confirmationSummary, journal.value.participants)).toEqual({ ok: true, value: journal.value.requiredLocks }); await expect(second.recover(preview.value.operationId, "rollback")).resolves.toMatchObject({ ok: true, value: { outcome: "rolled-back" } });
